import{_ as e,c as o,a0 as s,o as i}from"./chunks/framework.BGabeMLJ.js";const h=JSON.parse('{"title":"FAQs as User. Proposals & Analysis","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faqs/faqs-of-proposals-analysis.md","filePath":"guide/faqs/faqs-of-proposals-analysis.md"}'),t={name:"guide/faqs/faqs-of-proposals-analysis.md"};function r(n,a,l,d,p,c){return i(),o("div",null,a[0]||(a[0]=[s('<h1 id="faqs-as-user-proposals-analysis" tabindex="-1">FAQs as User. Proposals &amp; Analysis <a class="header-anchor" href="#faqs-as-user-proposals-analysis" aria-label="Permalink to &quot;FAQs as User. Proposals &amp; Analysis&quot;">​</a></h1><h3 id="how-do-i-get-started-as-a-user-on-flame" tabindex="-1">How do I get started as a User on FLAME? <a class="header-anchor" href="#how-do-i-get-started-as-a-user-on-flame" aria-label="Permalink to &quot;How do I get started as a User on FLAME?&quot;">​</a></h3><ol><li>Request Access: Contact the Hub administrator to be added to a Realm.</li><li>Receive Credentials: The assigned Admin of your organisation will get a login credentials for the Hub UI and provide you the necessary rights to login in the Hub.</li><li>Log In: Navigate to the Hub UI and log in with your credentials.</li><li>Explore Projects: Browse available projects and proposals in your Realm.</li><li>Submit Analysis Request: If approved, you can create an analysis for a project.</li><li>Write Your Code: Develop your analysis using the <a href="https://github.com/PrivateAIM/python-sdk.git" target="_blank" rel="noreferrer">FLAME Python SDK</a> as base for your entrypoint.</li><li>Test Locally: Test your analysis code locally before submitting to FLAME.</li><li>Submit for Review: Submit your script analysis to the Hub for node administrator approval.</li><li>Request your Node admin to set up a data store according to your analysis.</li><li>Monitor Execution: Once approved, execute your analysis across participating nodes.</li></ol><h3 id="what-is-a-proposal-in-flame" tabindex="-1">What is a Proposal in FLAME? <a class="header-anchor" href="#what-is-a-proposal-in-flame" aria-label="Permalink to &quot;What is a Proposal in FLAME?&quot;">​</a></h3><p>A proposal in FLAME defines a research initiative involving multiple organizations or nodes. It includes project metadata (title, description, objectives), specifies participating nodes/hospitals, and acts as a container for analyses. Approval from node administrators is required before running analyses, enabling federated analysis across institutions on the same dataset questions.</p><h3 id="how-do-i-submit-a-project-proposal" tabindex="-1">How do I submit a project proposal? <a class="header-anchor" href="#how-do-i-submit-a-project-proposal" aria-label="Permalink to &quot;How do I submit a project proposal?&quot;">​</a></h3><p>Create a proposal via Hub UI, specifying participants and details, then await administrative approval.</p><h3 id="how-do-i-write-and-code-an-analysis" tabindex="-1">How do I write and code an analysis? <a class="header-anchor" href="#how-do-i-write-and-code-an-analysis" aria-label="Permalink to &quot;How do I write and code an analysis?&quot;">​</a></h3><p>To write an analysis for FLAME, use the STAR pattern (Secure Training And Aggregation for Research) For more details, check <a href="/guide/user/analysis-coding.html">Analysis Coding</a> section of this documentation.</p><h3 id="can-i-test-my-analysis-locally-before-running-it-on-flame" tabindex="-1">Can I test my analysis locally before running it on FLAME? <a class="header-anchor" href="#can-i-test-my-analysis-locally-before-running-it-on-flame" aria-label="Permalink to &quot;Can I test my analysis locally before running it on FLAME?&quot;">​</a></h3><p>Yes, Use the <code>StarModelTester</code> for local testing before deployment. For further information, check <a href="/guide/user/local-testing.html">local-testing</a>.</p><h3 id="what-coding-examples-are-available" tabindex="-1">What coding examples are available? <a class="header-anchor" href="#what-coding-examples-are-available" aria-label="Permalink to &quot;What coding examples are available?&quot;">​</a></h3><p>Yes, though the documentation you will find examples suck like <a href="/guide/user/run-your-first-analysis.html">run-your-first-analysis</a> and further <strong>examples</strong> in the <a href="/guide/user/analysis-coding.html">Analysis Coding</a> section of this documentation.</p>',13)]))}const f=e(t,[["render",r]]);export{h as __pageData,f as default};
